-- S1: start date, the earliest of the semester start and the course's own content. COALESCE to a far -- future sentinel and NULLIF back, because MySQL LEAST returns NULL as soon as one argument is NULL -- while PostgreSQL and H2 skip NULLs. The sentinel keeps all three engines on the same result. UPDATE course SET start_date = NULLIF(LEAST( COALESCE(CASE WHEN semester REGEXP '^WS[0-9]{2}/[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS DATETIME) WHEN semester REGEXP '^SS[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS DATETIME) END, CAST('9999-12-31 00:00:00' AS DATETIME)), COALESCE((SELECT b.content_start FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('9999-12-31 00:00:00' AS DATETIME)) ), CAST('9999-12-31 00:00:00' AS DATETIME)) WHERE start_date IS NULL AND (end_date IS NULL OR NULLIF(LEAST( COALESCE(CASE WHEN semester REGEXP '^WS[0-9]{2}/[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS DATETIME) WHEN semester REGEXP '^SS[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS DATETIME) END, CAST('9999-12-31 00:00:00' AS DATETIME)), COALESCE((SELECT b.content_start FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('9999-12-31 00:00:00' AS DATETIME)) ), CAST('9999-12-31 00:00:00' AS DATETIME)) < end_date);
-- S2: end date, the latest of the semester end and the course's own content UPDATE course SET end_date = NULLIF(GREATEST( COALESCE(CASE WHEN semester REGEXP '^WS[0-9]{2}/[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS DATETIME) WHEN semester REGEXP '^SS[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS DATETIME) END, CAST('1000-01-01 00:00:00' AS DATETIME)), COALESCE((SELECT b.content_end FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('1000-01-01 00:00:00' AS DATETIME)) ), CAST('1000-01-01 00:00:00' AS DATETIME)) WHERE end_date IS NULL AND (start_date IS NULL OR NULLIF(GREATEST( COALESCE(CASE WHEN semester REGEXP '^WS[0-9]{2}/[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS DATETIME) WHEN semester REGEXP '^SS[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS DATETIME) END, CAST('1000-01-01 00:00:00' AS DATETIME)), COALESCE((SELECT b.content_end FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('1000-01-01 00:00:00' AS DATETIME)) ), CAST('1000-01-01 00:00:00' AS DATETIME)) > start_date);
-- S3 and S4: derive the missing bound from the one that is set UPDATE course SET start_date = DATE_SUB(end_date, INTERVAL 6 MONTH) WHERE start_date IS NULL AND end_date IS NOT NULL; UPDATE course SET end_date = DATE_ADD(start_date, INTERVAL 6 MONTH) WHERE end_date IS NULL AND start_date IS NOT NULL;
-- S5: the course request this course was created from knows when it was made UPDATE course SET start_date = (SELECT MIN(cr.created_date) FROM course_request cr WHERE cr.created_course_id = course.id) WHERE start_date IS NULL AND (SELECT MIN(cr.created_date) FROM course_request cr WHERE cr.created_course_id = course.id) IS NOT NULL;
-- S6 and S7: last resort for a course with no temporal information at all UPDATE course SET start_date = DATE_SUB(NOW(3), INTERVAL 3 MONTH) WHERE start_date IS NULL; UPDATE course SET end_date = DATE_ADD(start_date, INTERVAL 6 MONTH) WHERE end_date IS NULL;
-- S8: semester from the start date UPDATE course SET semester = CASE WHEN MONTH(start_date) >= 10 THEN CONCAT('WS', LPAD(YEAR(start_date) - 2000, 2, '0'), '/', LPAD(YEAR(start_date) - 1999, 2, '0')) WHEN MONTH(start_date) <= 3 THEN CONCAT('WS', LPAD(YEAR(start_date) - 2001, 2, '0'), '/', LPAD(YEAR(start_date) - 2000, 2, '0')) ELSE CONCAT('SS', LPAD(YEAR(start_date) - 2000, 2, '0')) END WHERE semester IS NULL OR semester = '';

-- S1: start date, the earliest of the semester start and the course's own content UPDATE course SET start_date = NULLIF(LEAST( COALESCE(CASE WHEN semester ~* '^WS[0-9]{2}/[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS TIMESTAMP) WHEN semester ~* '^SS[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS TIMESTAMP) END, CAST('9999-12-31 00:00:00' AS TIMESTAMP)), COALESCE((SELECT b.content_start FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) ), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) WHERE start_date IS NULL AND (end_date IS NULL OR NULLIF(LEAST( COALESCE(CASE WHEN semester ~* '^WS[0-9]{2}/[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS TIMESTAMP) WHEN semester ~* '^SS[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS TIMESTAMP) END, CAST('9999-12-31 00:00:00' AS TIMESTAMP)), COALESCE((SELECT b.content_start FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) ), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) < end_date);
-- S2: end date, the latest of the semester end and the course's own content UPDATE course SET end_date = NULLIF(GREATEST( COALESCE(CASE WHEN semester ~* '^WS[0-9]{2}/[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS TIMESTAMP) WHEN semester ~* '^SS[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS TIMESTAMP) END, CAST('1000-01-01 00:00:00' AS TIMESTAMP)), COALESCE((SELECT b.content_end FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('1000-01-01 00:00:00' AS TIMESTAMP)) ), CAST('1000-01-01 00:00:00' AS TIMESTAMP)) WHERE end_date IS NULL AND (start_date IS NULL OR NULLIF(GREATEST( COALESCE(CASE WHEN semester ~* '^WS[0-9]{2}/[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS TIMESTAMP) WHEN semester ~* '^SS[0-9]{2}$' THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS TIMESTAMP) END, CAST('1000-01-01 00:00:00' AS TIMESTAMP)), COALESCE((SELECT b.content_end FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('1000-01-01 00:00:00' AS TIMESTAMP)) ), CAST('1000-01-01 00:00:00' AS TIMESTAMP)) > start_date);
-- S3 and S4: derive the missing bound from the one that is set UPDATE course SET start_date = end_date - INTERVAL '6 months' WHERE start_date IS NULL AND end_date IS NOT NULL; UPDATE course SET end_date = start_date + INTERVAL '6 months' WHERE end_date IS NULL AND start_date IS NOT NULL;
-- S5: the course request this course was created from knows when it was made UPDATE course SET start_date = (SELECT MIN(cr.created_date) FROM course_request cr WHERE cr.created_course_id = course.id) WHERE start_date IS NULL AND (SELECT MIN(cr.created_date) FROM course_request cr WHERE cr.created_course_id = course.id) IS NOT NULL;
-- S6 and S7: last resort for a course with no temporal information at all UPDATE course SET start_date = CURRENT_TIMESTAMP - INTERVAL '3 months' WHERE start_date IS NULL; UPDATE course SET end_date = start_date + INTERVAL '6 months' WHERE end_date IS NULL;
-- S8: semester from the start date UPDATE course SET semester = CASE WHEN EXTRACT(MONTH FROM start_date) >= 10 THEN CONCAT('WS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS TEXT), 2, '0'), '/', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 1999 AS TEXT), 2, '0')) WHEN EXTRACT(MONTH FROM start_date) <= 3 THEN CONCAT('WS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2001 AS TEXT), 2, '0'), '/', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS TEXT), 2, '0')) ELSE CONCAT('SS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS TEXT), 2, '0')) END WHERE semester IS NULL OR semester = '';

-- S1: start date, the earliest of the semester start and the course's own content UPDATE course SET start_date = NULLIF(LEAST( COALESCE(CASE WHEN REGEXP_LIKE(semester, '^WS[0-9]{2}/[0-9]{2}$', 'i') THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS TIMESTAMP) WHEN REGEXP_LIKE(semester, '^SS[0-9]{2}$', 'i') THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS TIMESTAMP) END, CAST('9999-12-31 00:00:00' AS TIMESTAMP)), COALESCE((SELECT b.content_start FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) ), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) WHERE start_date IS NULL AND (end_date IS NULL OR NULLIF(LEAST( COALESCE(CASE WHEN REGEXP_LIKE(semester, '^WS[0-9]{2}/[0-9]{2}$', 'i') THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS TIMESTAMP) WHEN REGEXP_LIKE(semester, '^SS[0-9]{2}$', 'i') THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS TIMESTAMP) END, CAST('9999-12-31 00:00:00' AS TIMESTAMP)), COALESCE((SELECT b.content_start FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) ), CAST('9999-12-31 00:00:00' AS TIMESTAMP)) < end_date);
-- S2: end date, the latest of the semester end and the course's own content UPDATE course SET end_date = NULLIF(GREATEST( COALESCE(CASE WHEN REGEXP_LIKE(semester, '^WS[0-9]{2}/[0-9]{2}$', 'i') THEN CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS TIMESTAMP) WHEN REGEXP_LIKE(semester, '^SS[0-9]{2}$', 'i') THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS TIMESTAMP) END, CAST('1000-01-01 00:00:00' AS TIMESTAMP)), COALESCE((SELECT b.content_end FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('1000-01-01 00:00:00' AS TIMESTAMP)) ), CAST('1000-01-01 00:00:00' AS TIMESTAMP)) WHERE end_date IS NULL AND (start_date IS NULL OR NULLIF(GREATEST( COALESCE(CASE WHEN REGEXP_LIKE(semester, '^WS[0-9]{2}/[0-9]{2}$', 'i') THEN CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS TIMESTAMP) WHEN REGEXP_LIKE(semester, '^SS[0-9]{2}$', 'i') THEN CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS TIMESTAMP) END, CAST('1000-01-01 00:00:00' AS TIMESTAMP)), COALESCE((SELECT b.content_end FROM tmp_course_content_bounds b WHERE b.course_id = course.id), CAST('1000-01-01 00:00:00' AS TIMESTAMP)) ), CAST('1000-01-01 00:00:00' AS TIMESTAMP)) > start_date);
-- S3 and S4: derive the missing bound from the one that is set UPDATE course SET start_date = DATEADD('MONTH', -6, end_date) WHERE start_date IS NULL AND end_date IS NOT NULL; UPDATE course SET end_date = DATEADD('MONTH', 6, start_date) WHERE end_date IS NULL AND start_date IS NOT NULL;
-- S5: the course request this course was created from knows when it was made UPDATE course SET start_date = (SELECT MIN(cr.created_date) FROM course_request cr WHERE cr.created_course_id = course.id) WHERE start_date IS NULL AND (SELECT MIN(cr.created_date) FROM course_request cr WHERE cr.created_course_id = course.id) IS NOT NULL;
-- S6 and S7: last resort for a course with no temporal information at all UPDATE course SET start_date = DATEADD('MONTH', -3, CURRENT_TIMESTAMP) WHERE start_date IS NULL; UPDATE course SET end_date = DATEADD('MONTH', 6, start_date) WHERE end_date IS NULL;
-- S8: semester from the start date UPDATE course SET semester = CASE WHEN EXTRACT(MONTH FROM start_date) >= 10 THEN CONCAT('WS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS VARCHAR), 2, '0'), '/', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 1999 AS VARCHAR), 2, '0')) WHEN EXTRACT(MONTH FROM start_date) <= 3 THEN CONCAT('WS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2001 AS VARCHAR), 2, '0'), '/', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS VARCHAR), 2, '0')) ELSE CONCAT('SS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS VARCHAR), 2, '0')) END WHERE semester IS NULL OR semester = '';

-- S1: start date from the semester start
UPDATE course_request SET start_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS DATETIME)
WHERE start_date IS NULL AND semester REGEXP '^WS[0-9]{2}/[0-9]{2}$'
  AND (end_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS DATETIME) < end_date);
UPDATE course_request SET start_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS DATETIME)
WHERE start_date IS NULL AND semester REGEXP '^SS[0-9]{2}$'
  AND (end_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS DATETIME) < end_date);

-- S2: end date from the semester end
UPDATE course_request SET end_date = CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS DATETIME)
WHERE end_date IS NULL AND semester REGEXP '^WS[0-9]{2}/[0-9]{2}$'
  AND (start_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS DATETIME) > start_date);
UPDATE course_request SET end_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS DATETIME)
WHERE end_date IS NULL AND semester REGEXP '^SS[0-9]{2}$'
  AND (start_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS DATETIME) > start_date);

-- S3 and S4: derive the missing bound from the one that is set
UPDATE course_request SET start_date = DATE_SUB(end_date, INTERVAL 6 MONTH) WHERE start_date IS NULL AND end_date IS NOT NULL;
UPDATE course_request SET end_date = DATE_ADD(start_date, INTERVAL 6 MONTH) WHERE end_date IS NULL AND start_date IS NOT NULL;

-- S5: the request records when it was made
UPDATE course_request SET start_date = created_date WHERE start_date IS NULL AND created_date IS NOT NULL;

-- S6 and S7: last resort for a request with no temporal information at all
UPDATE course_request SET start_date = DATE_SUB(NOW(3), INTERVAL 3 MONTH) WHERE start_date IS NULL;
UPDATE course_request SET end_date = DATE_ADD(start_date, INTERVAL 6 MONTH) WHERE end_date IS NULL;

-- S8: semester from the start date
UPDATE course_request SET semester = CASE
        WHEN MONTH(start_date) >= 10 THEN CONCAT('WS', LPAD(YEAR(start_date) - 2000, 2, '0'), '/', LPAD(YEAR(start_date) - 1999, 2, '0'))
        WHEN MONTH(start_date) <= 3 THEN CONCAT('WS', LPAD(YEAR(start_date) - 2001, 2, '0'), '/', LPAD(YEAR(start_date) - 2000, 2, '0'))
        ELSE CONCAT('SS', LPAD(YEAR(start_date) - 2000, 2, '0'))
    END
WHERE semester IS NULL OR semester = '';

-- S1: start date from the semester start
UPDATE course_request SET start_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS TIMESTAMP)
WHERE start_date IS NULL AND semester ~* '^WS[0-9]{2}/[0-9]{2}$'
  AND (end_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS TIMESTAMP) < end_date);
UPDATE course_request SET start_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS TIMESTAMP)
WHERE start_date IS NULL AND semester ~* '^SS[0-9]{2}$'
  AND (end_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS TIMESTAMP) < end_date);

-- S2: end date from the semester end
UPDATE course_request SET end_date = CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS TIMESTAMP)
WHERE end_date IS NULL AND semester ~* '^WS[0-9]{2}/[0-9]{2}$'
  AND (start_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS TIMESTAMP) > start_date);
UPDATE course_request SET end_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS TIMESTAMP)
WHERE end_date IS NULL AND semester ~* '^SS[0-9]{2}$'
  AND (start_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS TIMESTAMP) > start_date);

-- S3 and S4: derive the missing bound from the one that is set
UPDATE course_request SET start_date = end_date - INTERVAL '6 months' WHERE start_date IS NULL AND end_date IS NOT NULL;
UPDATE course_request SET end_date = start_date + INTERVAL '6 months' WHERE end_date IS NULL AND start_date IS NOT NULL;

-- S5: the request records when it was made
UPDATE course_request SET start_date = created_date WHERE start_date IS NULL AND created_date IS NOT NULL;

-- S6 and S7: last resort for a request with no temporal information at all
UPDATE course_request SET start_date = CURRENT_TIMESTAMP - INTERVAL '3 months' WHERE start_date IS NULL;
UPDATE course_request SET end_date = start_date + INTERVAL '6 months' WHERE end_date IS NULL;

-- S8: semester from the start date
UPDATE course_request SET semester = CASE
        WHEN EXTRACT(MONTH FROM start_date) >= 10 THEN CONCAT('WS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS TEXT), 2, '0'), '/', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 1999 AS TEXT), 2, '0'))
        WHEN EXTRACT(MONTH FROM start_date) <= 3 THEN CONCAT('WS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2001 AS TEXT), 2, '0'), '/', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS TEXT), 2, '0'))
        ELSE CONCAT('SS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS TEXT), 2, '0'))
    END
WHERE semester IS NULL OR semester = '';

-- S1: start date from the semester start
UPDATE course_request SET start_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS TIMESTAMP)
WHERE start_date IS NULL AND REGEXP_LIKE(semester, '^WS[0-9]{2}/[0-9]{2}$', 'i')
  AND (end_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-10-01 00:00:00') AS TIMESTAMP) < end_date);
UPDATE course_request SET start_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS TIMESTAMP)
WHERE start_date IS NULL AND REGEXP_LIKE(semester, '^SS[0-9]{2}$', 'i')
  AND (end_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-04-01 00:00:00') AS TIMESTAMP) < end_date);

-- S2: end date from the semester end
UPDATE course_request SET end_date = CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS TIMESTAMP)
WHERE end_date IS NULL AND REGEXP_LIKE(semester, '^WS[0-9]{2}/[0-9]{2}$', 'i')
  AND (start_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 6, 2), '-03-31 23:59:59') AS TIMESTAMP) > start_date);
UPDATE course_request SET end_date = CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS TIMESTAMP)
WHERE end_date IS NULL AND REGEXP_LIKE(semester, '^SS[0-9]{2}$', 'i')
  AND (start_date IS NULL OR CAST(CONCAT('20', SUBSTRING(semester, 3, 2), '-09-30 23:59:59') AS TIMESTAMP) > start_date);

-- S3 and S4: derive the missing bound from the one that is set
UPDATE course_request SET start_date = DATEADD('MONTH', -6, end_date) WHERE start_date IS NULL AND end_date IS NOT NULL;
UPDATE course_request SET end_date = DATEADD('MONTH', 6, start_date) WHERE end_date IS NULL AND start_date IS NOT NULL;

-- S5: the request records when it was made
UPDATE course_request SET start_date = created_date WHERE start_date IS NULL AND created_date IS NOT NULL;

-- S6 and S7: last resort for a request with no temporal information at all
UPDATE course_request SET start_date = DATEADD('MONTH', -3, CURRENT_TIMESTAMP) WHERE start_date IS NULL;
UPDATE course_request SET end_date = DATEADD('MONTH', 6, start_date) WHERE end_date IS NULL;

-- S8: semester from the start date
UPDATE course_request SET semester = CASE
        WHEN EXTRACT(MONTH FROM start_date) >= 10 THEN CONCAT('WS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS VARCHAR), 2, '0'), '/', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 1999 AS VARCHAR), 2, '0'))
        WHEN EXTRACT(MONTH FROM start_date) <= 3 THEN CONCAT('WS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2001 AS VARCHAR), 2, '0'), '/', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS VARCHAR), 2, '0'))
        ELSE CONCAT('SS', LPAD(CAST(EXTRACT(YEAR FROM start_date) - 2000 AS VARCHAR), 2, '0'))
    END
WHERE semester IS NULL OR semester = '';
